/**
* 添加起火点
*/
function addFirePoint(point) {
  fireParticlePrimitive = viewer.scene.primitives.add(new Cesium.ParticleSystem({
      image: './resources/img/fire.png',
      startColor: new Cesium.Color(1, 1, 1, 1),
      endColor: new Cesium.Color(0.5, 0, 0, 0),

      startScale: style.startScale,
      endScale: style.endScale,
      minimumParticleLife: style.minimumParticleLife,
      maximumParticleLife: style.maximumParticleLife,
      minimumSpeed: style.minimumSpeed,
      maximumSpeed: style.maximumSpeed,
      imageSize: new Cesium.Cartesian2(style.particleSize, style.particleSize),
      emissionRate: style.emissionRate,

      lifetime: 16.0,
      loop: true,
      emitter: new Cesium.ConeEmitter(Cesium.Math.toRadians(45.0)),
      sizeInMeters: true,
      modelMatrix: Cesium.Transforms.eastNorthUpToFixedFrame(Cesium.Cartesian3.fromDegrees(point[0], point[1], getHeight(point) + 5))
  }));

}

/**
* 删除起火点
*/
function removeFirePoint() {
  if (fireParticlePrimitive) {
      viewer.scene.primitives.remove(fireParticlePrimitive);
      fireParticlePrimitive = null;
  }
}



/**
* 定位到火灾点
*/
function locationPoint(start) {
  viewer.scene.camera.flyTo({
      destination: new Cesium.Cartesian3.fromDegrees(start[0], start[1], 10000),
      duration: 2
  });
  setTimeout(() => {
      viewer.scene.camera.flyTo({
          destination: new Cesium.Cartesian3.fromDegrees(start[0], start[1] + 0.005, getHeight(start) + 500),
          orientation: {
              heading: Cesium.Math.toRadians(-180.0),
              pitch: Cesium.Math.toRadians(-35.0),
              roll: 0.0
          }
      });
  }, 2500)
}

/**
* 火灾蔓延（每次模拟制定时间）
*/
function spread(count) {
  if (!polygon) {
      angles = [];
      startPs = [];
      endPs = [];
      for (let i = 0; i < count; i++) {
          let angle = Math.PI * 2 / count * i;   //角度
          angles.push(angle);
          startPs.push(start);
          endPs.push(getEndPoint(start, angle, 0.0001));
      }

      polygon = viewer.entities.add({
          name: "Green extruded polygon",
          polygon: {
              hierarchy: new Cesium.CallbackProperty((time, result) => {
                  let position = new Cesium.Cartesian3.fromDegreesArray(endPs.flat(), Cesium.Ellipsoid.WGS84,
                      result)
                  return new Cesium.PolygonHierarchy(position)
              }, false),
              // extrudedHeight: 500000.0,
              material: Cesium.Color.RED.withAlpha(0.8),
              closeTop: false,
              closeBottom: false
          }
      });
  }

  //
  let tempPs = [];
  for (let j = 0; j < angles.length; j++) {
      let startP = startPs[j];
      let endP = endPs[j];
      let angle = angles[j];
      let slope = getSlope(startP, angle);
      let speed = getgrove(tempf, slope) / (60 / timeStep);  //蔓延速度
      let length = speed * Math.abs(Math.cos(slope / 180 * Math.PI));
      let tempP = getEndPoint(endP, angle, speed);
      tempPs.push(tempP);
  }
  startPs = endPs;
  endPs = tempPs;
}


/**
* 获取点高度
* @param {Array<Number>} point 经纬度点坐标  
* @return {number} 指定点高度
*/
function getHeight(point) {
  let cartographic = Cesium.Cartographic.fromDegrees(point[0], point[1]);
  let height = viewer.scene.globe.getHeight(cartographic);
  return height
}

/**
* 获取坡度
* @param {Array<Number>}  start 起点坐标
* @param {Number} angle 角度
*/
function getSlope(start, angle) {
  let end = getEndPoint(start, angle, 0.000001);
  let startH = getHeight(start);

  let endH = getHeight(end);
  var slope = Math.atan((startH - endH) / (Cesium.Cartesian3.distance(
      Cesium.Cartesian3.fromDegrees(start[0], start[1], startH),
      Cesium.Cartesian3.fromDegrees(end[0], end[1], endH)))) / Math.PI * 180

  return -slope;
}
/**
*  计算下一个火灾点
* @param {Array<Number>} 起点坐标
* @param {Number} angle 角度
* @param {Number} speed 速度 
*/
function getEndPoint(start, angle, speed) {
  let xStep = Math.sin(angle) * speed;
  let yStep = Math.cos(angle) * speed;
  let cartesian = new Cesium.Cartesian3.fromDegrees(start[0], start[1])
  cartesian.x += xStep;
  cartesian.y += yStep;
  let ellipsoid = viewer.scene.globe.ellipsoid;
  let cartographic = ellipsoid.cartesianToCartographic(cartesian);

  return [Cesium.Math.toDegrees(cartographic.longitude), Cesium.Math.toDegrees(cartographic.latitude)];
}


/**
* 获取蔓延速度(米/小时)
* @param {Number} tempf 火险指数:可自行设置任意数测试
* @param {Number} slope 坡度
* @return {NUmber} 速度
*/
function getgrove(tempf, slope) {
  return 0.13 * tempf * Math.exp(0.064 * slope) * 1000;
}

